<template><div class="page-card"><h2>借阅管理</h2><el-table :data="rows"><el-table-column prop="bookTitle" label="图书"/><el-table-column prop="readerName" label="读者"/><el-table-column prop="borrowTime" label="借出时间"/><el-table-column prop="dueTime" label="应还时间"/><el-table-column prop="status" label="状态"/><el-table-column label="操作"><template #default="s"><el-button v-if="s.row.status===1" link type="primary" @click="returnBook(s.row)">归还</el-button></template></el-table-column></el-table></div></template>
<script setup>import {ref,onMounted} from 'vue';import {ElMessage} from 'element-plus';import http from '../api/http';const rows=ref([]);async function load(){const r=await http.get('/borrows',{params:{page:1,size:50}});rows.value=r.data.records}async function returnBook(row){const r=await http.put('/borrows/return',{recordId:row.id,status:2});if(r.code===200){ElMessage.success('归还成功');load()}}onMounted(load)</script>
